// R5/B-1: arma el prompt del validador de repreguntas. El mensaje del cliente y la
// conversacion van DELIMITADOS (recomendacion de Fable): input como dato, nunca
// mezclado con las instrucciones del system message.
const d = $('Leer Selector').first().json;
const conv = Array.isArray(d.conversation) ? d.conversation : [];
const ultimos = conv.slice(-6)
  .map((m) => (m.role === 'user' ? 'CLIENTE: ' : 'NOSOTROS: ') + String(m.content || ''))
  .join('\n');
const pregunta = String((d.seleccion || {}).pregunta || '');
return [{ json: { ...d, promptAgente: [
  '<conversacion>',
  ultimos || '(sin historial)',
  '</conversacion>',
  '',
  '<ultimo_mensaje>',
  String(d.userMessage || ''),
  '</ultimo_mensaje>',
  '',
  '<repregunta_selector>',
  pregunta || '(el Selector no dejo una repregunta)',
  '</repregunta_selector>',
].join('\n') } }];
